def _run(args: list[str], timeout: int = 20) -> str:
    r = subprocess.run(args, capture_output=True, text=True, timeout=timeout)
    if r.returncode:
        raise RuntimeError(f"{args!r}: {r.returncode}: {r.stderr}")
    return r.stdout


def _sha(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def _physical(path: Path) -> Path:
    if not path.is_absolute() or path.resolve(strict=False) != path or not path.is_relative_to(B):
        raise RuntimeError(f"path escaped physical B: {path}")
    return path


def _write(path: Path, value: dict[str, object]) -> None:
    raw = (json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n").encode()
    with path.open("xb") as f:
        f.write(raw)
        f.flush()
        os.fsync(f.fileno())


def _unit(unit: str, fields: list[str]) -> dict[str, str]:
    args = ["systemctl", "--user", "show", "--all", unit]
    args.extend(part for field in fields for part in ("-p", field))
    return dict(line.split("=", 1) for line in _run(args).splitlines())


def _data_identity() -> dict[str, dict[str, object]]:
    _physical(REGISTRY)
    if REGISTRY.is_symlink() or _sha(REGISTRY) != P["registry_sha256"]:
        raise RuntimeError("portable data registry changed")
    sources = json.loads(REGISTRY.read_bytes()).get("sources", {})
    expected = P["data_resolution_map"]
    if set(sources) != set(expected) or len(expected) != 6:
        raise RuntimeError("registered F0 source membership changed")
    root, data = B.resolve(strict=True), DATA.resolve(strict=True)
    if not data.is_relative_to(root):
        raise RuntimeError("data root escaped B")
    out = {}
    for rel, bound in expected.items():
        path = DATA / rel
        entry = sources[rel]
        resolved = path.resolve(strict=True)
        st = resolved.stat()
        obs = {
            "path": str(path),
            "resolved": str(resolved),
            "islink": path.is_symlink(),
            "device": st.st_dev,
            "bytes": st.st_size,
            "inode": st.st_ino,
            "mtime_ns": st.st_mtime_ns,
            "registered_sha256": entry.get("sha256"),
        }
        keys = (
            "path",
            "resolved",
            "islink",
            "device",
            "bytes",
            "inode",
            "mtime_ns",
            "registered_sha256",
        )
        if (
            not stat.S_ISREG(st.st_mode)
            or obs != {k: bound[k] for k in keys}
            or st.st_dev != root.stat().st_dev
            or st.st_size != entry.get("original_identity", {}).get("bytes")
        ):
            raise RuntimeError(f"registered dataset alias/stat changed: {rel}")
        out[rel] = obs
    return out


def _parent() -> tuple[dict[str, str], dict[str, str], Path]:
    keys = [
        "ControlGroup",
        "MemoryCurrent",
        "MemoryHigh",
        "MemoryMax",
        "MemorySwapMax",
        "CPUQuotaPerSecUSec",
    ]
    p = _unit("wnn-campaign.slice", keys)
    if (
        not p.get("ControlGroup")
        or p["ControlGroup"] == "/"
        or (p["CPUQuotaPerSecUSec"], p["MemoryHigh"], p["MemoryMax"], p["MemorySwapMax"])
        != ("2s", "18000000000", "20000000000", "0")
        or int(p["MemoryCurrent"]) + FIT_MEMORY >= 17_000_000_000
    ):
        raise RuntimeError(f"campaign parent limits/headroom failed: {p}")
    group = Path("/sys/fs/cgroup") / p["ControlGroup"].lstrip("/")
    files = [group / "cgroup.procs", *group.rglob("cgroup.procs")]
    if len(files) > 128:
        raise RuntimeError("campaign cgroup scan exceeded bound")
    populated = {str(x): v for x in files if (v := x.read_text().strip())}
    if populated:
        raise RuntimeError(f"campaign cgroup is populated: {populated}")
    return p, populated, group


def _gpu() -> tuple[str, list[dict[str, object]]]:
    prefix = ["nvidia-smi", "-i", GPU]
    status = _run(
        prefix + ["--query-gpu=uuid,name,memory.free,memory.total", "--format=csv,noheader"]
    )
    cols = [x.strip() for x in status.strip().split(",")]
    if len(cols) != 4 or cols[0] != GPU or int(cols[2].split()[0]) * 1024 * 1024 < MIN_GPU_FREE:
        raise RuntimeError("selected GPU identity/free reserve failed")
    out = _run(prefix + ["--query-compute-apps=pid,gpu_uuid,used_memory", "--format=csv,noheader"])
    kept = []
    for row in out.splitlines():
        c = [x.strip() for x in row.split(",")]
        if row.strip().startswith("No running processes found"):
            continue
        if len(c) != 3 or c[1] != GPU:
            raise RuntimeError("unexpected selected-GPU process row")
        proc = Path("/proc") / c[0]
        try:
            owner = (proc / "cgroup").read_text().strip()
            uid = proc.stat().st_uid
            cmd = (proc / "cmdline").read_bytes().decode(errors="replace")
        except FileNotFoundError:
            kept.append({"pid": c[0], "exited_during_observation": True})
            continue
        if "wnn-campaign.slice" in owner or (uid == os.getuid() and str(B) in cmd):
            raise RuntimeError(f"selected GPU owned by another campaign process: {c[0]}")
        kept.append(
            {"pid": c[0], "uid": uid, "cgroup": owner, "used_memory": c[2], "preserved": True}
        )
    return status.strip(), kept


def _source_identity() -> int:
    raw = base64.b64decode(P["source_manifest_b64"], validate=True)
    if hashlib.sha256(raw).hexdigest() != P["source_manifest_sha256"]:
        raise RuntimeError("embedded source manifest changed")
    manifest = json.loads(raw)
    if (
        manifest.get("source_commit") != P["source_commit"]
        or manifest.get("source_root") != str(SOURCE)
        or len(manifest.get("files", [])) != 167
        or P["source_commit"] != "68ff682977b822f38351aac0f621146f5f13b440"
    ):
        raise RuntimeError("source manifest identity differs")
    expected = {item["path"] for item in manifest["files"]}
    actual = set()
    for item in manifest["files"]:
        path = SOURCE / item["path"]
        if (
            path.is_symlink()
            or not path.is_file()
            or path.stat().st_size != item["bytes"]
            or _sha(path) != item["sha256"]
        ):
            raise RuntimeError(f"source differs from manifest: {item['path']}")
        actual.add(item["path"])
    existing = {
        x.relative_to(SOURCE).as_posix() for x in SOURCE.rglob("*") if x.is_file() or x.is_symlink()
    }
    if actual != expected or existing != expected or SOURCE.is_symlink() or not SOURCE.is_dir():
        raise RuntimeError("staged source inventory is incomplete, extra, or unsafe")
    return len(actual)


def _metadata_identity() -> dict[str, str]:
    _physical(CONTRACT)
    if CONTRACT.is_symlink() or _sha(CONTRACT) != P["contract_sha256"]:
        raise RuntimeError("cache execution contract changed")
    doc = json.loads(CONTRACT.read_bytes())
    if doc.get("split_sha256") != P["split_sha256"] or doc.get("teacher_order") != [3, 4, 5]:
        raise RuntimeError("cache contract split/order differs")
    pins = {"preparation/TEACHER_CACHE_EXECUTION_CONTRACT_R1.json": P["contract_sha256"]}
    for item in P["teacher_metadata"]:
        path = _physical(TEACHER_ROOT / item["path"])
        if path.is_symlink() or _sha(path) != item["sha256"]:
            raise RuntimeError(f"accepted teacher metadata changed: {item['run']}")
        pins[item["path"]] = item["sha256"]
    return pins


def _group_list(value: object, label: str) -> list[int]:
    if not isinstance(value, list) or any(type(group) is not int for group in value):
        raise RuntimeError(f"cache group membership is not an integer list: {label}")
    if len(value) != len(set(value)):
        raise RuntimeError(f"cache group membership has duplicates: {label}")
    return value


def _validate_cache_membership(
    metadata: dict[str, object], canonical_split: dict[str, object]
) -> None:
    fit = metadata.get("fit_groups")
    expected_fit = canonical_split.get("fit")
    evaluation = canonical_split.get("evaluation")
    if (
        not isinstance(fit, dict)
        or not isinstance(expected_fit, dict)
        or not isinstance(evaluation, dict)
    ):
        raise RuntimeError("canonical split membership is missing")
    train = _group_list(fit.get("train"), "fit train")
    valid = _group_list(fit.get("valid"), "fit valid")
    expected_train = _group_list(expected_fit.get("train"), "canonical fit train")
    expected_valid = _group_list(expected_fit.get("valid"), "canonical fit valid")
    outer = _group_list(metadata.get("evaluation_valid_groups"), "metadata outer valid")
    expected_outer = _group_list(evaluation.get("valid"), "canonical outer valid")
    counts = (len(train), len(valid), len(outer))
    if (
        train != expected_train
        or valid != expected_valid
        or outer != expected_outer
        or counts != (10535, 1405, 468)
    ):
        raise RuntimeError("cache fit memberships differ from canonical split by namespace")
    if set(valid) & set(outer):
        raise RuntimeError("cache fit-valid membership overlaps outer-valid membership")
    files = metadata.get("files")
    if not isinstance(files, dict):
        raise RuntimeError("cache file membership manifest is missing")
    for split, groups in (("train", train), ("valid", valid)):
        entry = files.get(f"main_homogeneous_{split}")
        if not isinstance(entry, dict):
            raise RuntimeError(f"cache file membership is missing: {split}")
        rows = _group_list(entry.get("row_groups"), f"output {split}")
        if len(rows) != len(groups) or set(rows) != set(groups):
            raise RuntimeError(f"cache output membership differs: {split}")


def _cache_identity() -> dict[str, object]:
    p = P["cache_binding"]
    fields = (
        "acceptance_path",
        "acceptance_sha256",
        "exact_stop_path",
        "exact_stop_sha256",
        "unit",
        "invocation_id",
        "metadata_sha256",
    )
    if any(not p.get(k) for k in fields) or any(
        v is None for s in ("train", "valid") for v in p["arrays"][s].values()
    ):
        raise RuntimeError("cache root acceptance/stop/metadata/output-stat binding is pending")
    for k, sha in (
        ("acceptance_path", "acceptance_sha256"),
        ("exact_stop_path", "exact_stop_sha256"),
    ):
        path = Path(p[k])
        _physical(path)
        if path.is_symlink() or _sha(path) != p[sha]:
            raise RuntimeError(f"cache receipt pin changed/escaped B: {k}")
    accept = json.loads(Path(p["acceptance_path"]).read_bytes())
    if accept.get("status") != "ACCEPTED":
        raise RuntimeError("cache root receipt is not accepted")
    stop = json.loads(Path(p["exact_stop_path"]).read_bytes())
    before = stop.get("before", {}).get(p["unit"], {})
    after = stop.get("after", {}).get(p["unit"], {})
    done = stop.get("stop", {}).get(p["unit"], {})
    if (
        before.get("InvocationID") != p["invocation_id"]
        or before.get("ExecMainStatus") != "0"
        or done.get("returncode") != 0
        or after.get("LoadState") != "not-found"
        or after.get("ActiveState") != "inactive"
        or after.get("SubState") != "dead"
        or after.get("InvocationID") != ""
        or stop.get("populated") != {}
    ):
        raise RuntimeError("cache exact-stop does not bind the accepted completed unit")
    _physical(CACHE)
    mp = CACHE / "metadata.json"
    if mp.is_symlink() or mp.stat().st_size > 512_000 or _sha(mp) != p["metadata_sha256"]:
        raise RuntimeError("accepted cache metadata changed")
    m = json.loads(mp.read_bytes())
    target = m.get("target_contract", {})
    if (
        m.get("cache_profile") != "cleanfold_homogeneous_strong_t3_v1"
        or m.get("split_manifest_sha256") != P["split_sha256"]
        or m.get("homogeneous_scale") != 0.8125
        or m.get("stored_targets") != ["main_homogeneous"]
        or m.get("root_execution_contract", {}).get("sha256") != P["contract_sha256"]
    ):
        raise RuntimeError("cache source/target metadata differs")
    if target != {
        "formula": "float32(0.8125 * float32_mean(three_epoch2_predictions))",
        "teacher_epoch": 2,
        "teacher_mean": "unweighted arithmetic mean in float32",
        "clipping": "none during cache construction",
        "coefficient_multiplier": 0.8125,
    }:
        raise RuntimeError("cache arithmetic contract differs")
    _physical(SPLIT)
    if SPLIT.is_symlink():
        raise RuntimeError("canonical split path became a symlink")
    split_raw = SPLIT.read_bytes()
    if len(split_raw) > 4 * (1 << 20) or hashlib.sha256(split_raw).hexdigest() != P["split_sha256"]:
        raise RuntimeError("canonical split bytes changed or exceeded bound")
    _validate_cache_membership(m, json.loads(split_raw))
    coeff = m.get("source_coefficients", [])
    expected = [
        ("fg19_t3_h384x2_e3_s3_v1", 3),
        ("fg19_t3_h384x2_e3_s4_v1", 4),
        ("fg19_t3_h384x2_e3_s5_v1", 5),
    ]
    if [
        (x.get("run"), x.get("epoch"), x.get("family"), float(x.get("coefficient", 0)))
        for x in coeff
    ] != [(r, 2, "strong", 0.1) for r, _ in expected]:
        raise RuntimeError("cache teacher order/coefficients differ")
    stats = {}
    for split, rows in (("train", 10535), ("valid", 1405)):
        name = f"main_homogeneous_{split}.npy"
        path = _physical(CACHE / name)
        pin = p["arrays"][split]
        st = os.stat(path, follow_symlinks=False)
        observed = {
            "bytes": st.st_size,
            "device": st.st_dev,
            "inode": st.st_ino,
            "mtime_ns": st.st_mtime_ns,
        }
        entry = m.get("files", {}).get(f"main_homogeneous_{split}", {})
        if (
            path.is_symlink()
            or not stat.S_ISREG(st.st_mode)
            or observed != pin
            or entry.get("path") != name
            or entry.get("bytes") != st.st_size
            or entry.get("shape") != [rows, 20000, 2]
            or entry.get("dtype") != "float32"
        ):
            raise RuntimeError(f"cache output identity/stat/membership differs: {name}")
        stats[split] = observed
    return {
        "acceptance_sha256": p["acceptance_sha256"],
        "exact_stop_sha256": p["exact_stop_sha256"],
        "unit": p["unit"],
        "invocation_id": p["invocation_id"],
        "metadata_sha256": p["metadata_sha256"],
        "array_stats_only": stats,
    }


def _dictionary_identity() -> dict[str, object]:
    """Verify only the small accepted dictionary artifact, without deserializing it."""
    path = DICTIONARY_CACHE.resolve(strict=True)
    _physical(path)
    st = os.stat(path, follow_symlinks=False)
    if (
        not stat.S_ISREG(st.st_mode)
        or st.st_size != DICTIONARY_BYTES
        or _sha(path) != DICTIONARY_SHA256
    ):
        raise RuntimeError("shared dictionary cache bytes/stat differ from the accepted artifact")
    return {
        "path": str(path),
        "bytes": st.st_size,
        "device": st.st_dev,
        "inode": st.st_ino,
        "sha256": DICTIONARY_SHA256,
    }


def _parent_checkpoint_identity() -> dict[str, object]:
    """Recheck the accepted initialization checkpoint before creating profile inputs."""
    path = _physical(PARENT_CHECKPOINT)
    st = os.stat(path, follow_symlinks=False)
    if (
        path.is_symlink()
        or not stat.S_ISREG(st.st_mode)
        or st.st_size != PARENT_EP3_BYTES
        or _sha(path) != PARENT_EP3_SHA256
    ):
        raise RuntimeError("accepted parent epoch-3 checkpoint bytes/stat changed")
    return {
        "path": str(path),
        "bytes": st.st_size,
        "sha256": PARENT_EP3_SHA256,
        "device": st.st_dev,
        "inode": st.st_ino,
        "mtime_ns": st.st_mtime_ns,
    }


def _sync_directory(path: Path) -> None:
    descriptor = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def _decode_staged_receipts() -> tuple[dict[str, bytes], dict[str, str]]:
    """Decode and validate exact parent and dictionary receipts before staging."""
    payload = json.loads(base64.b64decode(STAGED_RECEIPTS_B64, validate=True))
    files = payload.get("files")
    expected = {
        PARENT_TERMINAL_ACCEPTANCE: PARENT_ACCEPTANCE_SHA256,
        PARENT_EXACT_STOP: PARENT_EXACT_STOP_SHA256,
        DICTIONARY_ACCEPTANCE: DICTIONARY_ACCEPTANCE_SHA256,
        DICTIONARY_EXACT_STOP: DICTIONARY_EXACT_STOP_SHA256,
    }
    if not isinstance(files, dict) or set(files) != set(expected):
        raise RuntimeError("EMA staged receipt membership changed")
    raw_files: dict[str, bytes] = {}
    pins: dict[str, str] = {}
    for name, expected_sha in expected.items():
        item = files[name]
        if not isinstance(item, dict) or not item.get("source_path"):
            raise RuntimeError(f"staged receipt source is missing: {name}")
        raw = base64.b64decode(item.get("raw_b64", ""), validate=True)
        digest = hashlib.sha256(raw).hexdigest()
        if digest != expected_sha or item.get("sha256") != digest:
            raise RuntimeError(f"staged receipt bytes differ from pin: {name}")
        raw_files[name] = raw
        pins[name] = digest
    acceptance = json.loads(raw_files[PARENT_TERMINAL_ACCEPTANCE])
    native = acceptance.get("native_unit", {})
    checkpoint = acceptance.get("files", {}).get("model_ep3.pt", {})
    if (
        acceptance.get("status") != "ACCEPTED"
        or acceptance.get("unit") != PARENT_UNIT
        or acceptance.get("invocation_id") != PARENT_INVOCATION
        or acceptance.get("selected_epoch") != 3
        or acceptance.get("successful_updates") != 29840
        or acceptance.get("nonfinite_updates") != 0
        or checkpoint.get("sha256") != PARENT_EP3_SHA256
        or checkpoint.get("bytes") != PARENT_EP3_BYTES
        or native.get("InvocationID") != PARENT_INVOCATION
        or native.get("MainPID") != "0"
        or native.get("ExecMainCode") != "1"
        or native.get("ExecMainStatus") != "0"
    ):
        raise RuntimeError("parent receipt is not the accepted epoch-3 fit")
    stop = json.loads(raw_files[PARENT_EXACT_STOP])
    before = stop.get("before", {})
    after = stop.get("after", {})
    stopped = stop.get("stop", {})
    if (
        stop.get("unit") != PARENT_UNIT
        or stop.get("invocation_id") != PARENT_INVOCATION
        or before.get("InvocationID") != PARENT_INVOCATION
        or before.get("ActiveState") != "active"
        or before.get("SubState") != "exited"
        or before.get("MainPID") != "0"
        or stopped.get("returncode") != 0
        or after.get("LoadState") != "not-found"
        or after.get("ActiveState") != "inactive"
        or after.get("SubState") != "dead"
        or after.get("MainPID") != "0"
        or after.get("InvocationID") != ""
        or stop.get("populated_after") != {}
    ):
        raise RuntimeError("parent exact-stop receipt does not bind the accepted fit")
    dictionary = json.loads(raw_files[DICTIONARY_ACCEPTANCE])
    cache = dictionary.get("cache", {})
    if (
        dictionary.get("status") != "ARTIFACT_AND_PROVENANCE_ACCEPTED"
        or dictionary.get("invocation") != DICTIONARY_INVOCATION_ID
        or cache.get("sha256") != DICTIONARY_SHA256
        or cache.get("bytes") != DICTIONARY_BYTES
        or Path(cache.get("path", "")).resolve(strict=False)
        != DICTIONARY_CACHE.resolve(strict=False)
    ):
        raise RuntimeError("dictionary acceptance differs from the accepted shared artifact")
    dictionary_stop = json.loads(raw_files[DICTIONARY_EXACT_STOP])
    if (
        dictionary_stop.get("before", {}).get("InvocationID") != DICTIONARY_INVOCATION_ID
        or dictionary_stop.get("before", {}).get("ActiveState") != "active"
        or dictionary_stop.get("before", {}).get("SubState") != "exited"
        or dictionary_stop.get("stop_returncode") != 0
        or dictionary_stop.get("after", {}).get("LoadState") != "not-found"
        or dictionary_stop.get("after", {}).get("ActiveState") != "inactive"
        or dictionary_stop.get("after", {}).get("SubState") != "dead"
        or dictionary_stop.get("after", {}).get("InvocationID") != ""
        or dictionary_stop.get("populated") != {}
    ):
        raise RuntimeError("dictionary exact-stop receipt does not bind its completed unit")
    return raw_files, pins


def _profile_receipt_bytes() -> tuple[bytes, bytes]:
    """Require pinned accepted profile receipt bytes before any remote mutation."""
    pending = (
        PROFILE_ACCEPTANCE_SHA256,
        PROFILE_EXACT_STOP_SHA256,
        PROFILE_INVOCATION_ID,
        PROFILE_ACCEPTANCE_B64,
        PROFILE_EXACT_STOP_B64,
    )
    if any(value.startswith("PENDING_") for value in pending):
        raise RuntimeError("all-three profile acceptance/stop receipts are not bound")
    acceptance_raw = base64.b64decode(PROFILE_ACCEPTANCE_B64, validate=True)
    stop_raw = base64.b64decode(PROFILE_EXACT_STOP_B64, validate=True)
    if (
        hashlib.sha256(acceptance_raw).hexdigest() != PROFILE_ACCEPTANCE_SHA256
        or hashlib.sha256(stop_raw).hexdigest() != PROFILE_EXACT_STOP_SHA256
    ):
        raise RuntimeError("embedded child-profile receipt bytes do not match their pins")
    return acceptance_raw, stop_raw


def _is_sha256(value: object) -> bool:
    return (
        isinstance(value, str)
        and len(value) == 64
        and all(character in "0123456789abcdef" for character in value)
    )


def _profile_identity(acceptance_raw: bytes, stop_raw: bytes) -> dict[str, object]:
    """Bind accepted profile receipts to its captured proof files without loading arrays."""
    acceptance = json.loads(acceptance_raw)
    invocation_id = acceptance.get("invocation_id")
    native = acceptance.get("native_unit", {})
    if (
        acceptance.get("schema") != "fg19-child-allthree-profile-terminal-acceptance.v1"
        or acceptance.get("status") != "ACCEPTED"
        or acceptance.get("unit") != PROFILE_UNIT
        or invocation_id != PROFILE_INVOCATION_ID
        or acceptance.get("main_pid") != 0
        or type(acceptance.get("main_pid")) is not int
        or acceptance.get("exec_main_code") != 1
        or type(acceptance.get("exec_main_code")) is not int
        or acceptance.get("exec_main_status") != 0
        or type(acceptance.get("exec_main_status")) is not int
        or native.get("InvocationID") != PROFILE_INVOCATION_ID
        or native.get("MainPID") != "0"
        or native.get("ExecMainCode") != "1"
        or native.get("ExecMainStatus") != "0"
        or native.get("ActiveState") != "active"
        or native.get("SubState") != "exited"
        or acceptance.get("source_commit") != P["source_commit"]
        or acceptance.get("source_file_count") != 167
        or acceptance.get("optimizer_attempts") != 60
        or acceptance.get("optimizer_completed_updates") != 60
        or acceptance.get("amp_skipped_updates") != 0
        or acceptance.get("gradient_stats_nonfinite_steps") != 0
        or acceptance.get("no_checkpoint") is not True
        or acceptance.get("scientific_fits") != 0
        or acceptance.get("quality_score") is not None
        or acceptance.get("stop_status") != "PENDING_EXACT_STOP"
    ):
        raise RuntimeError("accepted profile receipt identity/counters differ")
    if (
        type(acceptance.get("scientific_fits")) is not int
        or type(acceptance.get("optimizer_attempts")) is not int
    ):
        raise RuntimeError("profile counters are not typed integers")
    evidence = acceptance.get("profile_update_evidence", {})
    if (
        evidence.get("optimizer_attempts") != 60
        or evidence.get("optimizer_completed_updates") != 60
        or evidence.get("amp_skipped_updates") != 0
        or evidence.get("gradient_stats_nonfinite_steps") != 0
        or evidence.get("counts_consistent") is not True
        or evidence.get("valid_for_throughput") is not True
        or evidence.get("loss_finite") is not True
        or evidence.get("gradient_finite") is not True
    ):
        raise RuntimeError("profile update evidence is incomplete or inconsistent")
    initial_state = acceptance.get("initial_state")
    if not isinstance(initial_state, dict):
        raise RuntimeError("profile acceptance lacks its initial-state proof")
    _validate_profile_initial_state(initial_state)
    stop = json.loads(stop_raw)
    before = stop.get("before", {})
    after = stop.get("after", {})
    stopped = stop.get("stop", {})
    if (
        stop.get("unit") != PROFILE_UNIT
        or stop.get("invocation_id") != PROFILE_INVOCATION_ID
        or before.get("InvocationID") != PROFILE_INVOCATION_ID
        or before.get("ActiveState") != "active"
        or before.get("SubState") != "exited"
        or before.get("MainPID") != "0"
        or stopped.get("returncode") != 0
        or after.get("LoadState") != "not-found"
        or after.get("ActiveState") != "inactive"
        or after.get("SubState") != "dead"
        or after.get("MainPID") != "0"
        or after.get("InvocationID") != ""
        or stop.get("populated_after") != {}
    ):
        raise RuntimeError("profile exact-stop receipt does not bind the accepted invocation")
    _physical(PROFILE_OUTPUT)
    if PROFILE_OUTPUT.is_symlink() or not PROFILE_OUTPUT.is_dir():
        raise RuntimeError("accepted profile evidence directory is missing or unsafe")
    run_directory = acceptance.get("run_directory_stat_only")
    if run_directory != {"entries": [], "exists": True, "symlink": False}:
        raise RuntimeError("accepted profile run directory was not observed empty")
    _physical(PROFILE_RUN_DIR)
    if not os.path.lexists(PROFILE_RUN_DIR) or PROFILE_RUN_DIR.is_symlink():
        raise RuntimeError("accepted profile run directory is missing or unsafe")
    run_stat = os.stat(PROFILE_RUN_DIR, follow_symlinks=False)
    if not stat.S_ISDIR(run_stat.st_mode):
        raise RuntimeError("accepted profile run path is not a physical directory")
    with os.scandir(PROFILE_RUN_DIR) as run_entries:
        if next(run_entries, None) is not None:
            raise RuntimeError("profile wrote a persistent run artifact")
    file_pins = acceptance.get("files")
    required_files = {"ADMISSION.json", "LAUNCH.json", "unit.log"}
    if not isinstance(file_pins, dict) or set(file_pins) != required_files:
        raise RuntimeError("profile accepted file map does not bind admission, launch, and log")
    observed_files: dict[str, dict[str, object]] = {}
    file_bytes: dict[str, bytes] = {}
    for name in sorted(required_files):
        pin = file_pins[name]
        path = _physical(PROFILE_OUTPUT / name)
        st = os.stat(path, follow_symlinks=False)
        if (
            path.is_symlink()
            or not stat.S_ISREG(st.st_mode)
            or st.st_size != pin.get("bytes")
            or not _is_sha256(pin.get("sha256"))
            or st.st_size > 1_000_000
            or _sha(path) != pin["sha256"]
        ):
            raise RuntimeError(f"profile evidence file differs from accepted stat/hash: {name}")
        observed_files[name] = {"bytes": st.st_size, "sha256": pin["sha256"]}
        file_bytes[name] = path.read_bytes()
    admission = json.loads(file_bytes["ADMISSION.json"])
    launch = json.loads(file_bytes["LAUNCH.json"])
    if (
        admission.get("schema") != "fg19-child-allthree-profile-admission.v1"
        or admission.get("unit") != PROFILE_UNIT
        or admission.get("run_name") != PROFILE_RUN
        or admission.get("source_commit") != P["source_commit"]
        or admission.get("source_manifest_sha256") != P["source_manifest_sha256"]
        or admission.get("source_files_verified") != 167
        or admission.get("parent_acceptance_sha256") != PARENT_ACCEPTANCE_SHA256
        or admission.get("parent_exact_stop_sha256") != PARENT_EXACT_STOP_SHA256
        or admission.get("parent_checkpoint_sha256") != PARENT_EP3_SHA256
        or admission.get("dictionary", {}).get("sha256") != DICTIONARY_SHA256
        or launch.get("schema") != "fg19-child-allthree-profile-launch.v1"
        or launch.get("unit") != PROFILE_UNIT
    ):
        raise RuntimeError("captured profile admission/launch identity differs")
    log = file_bytes["unit.log"].decode("utf-8")
    proof_lines = [
        line.removeprefix("CHILD_PROFILE_INITIAL_STATE ")
        for line in log.splitlines()
        if line.startswith("CHILD_PROFILE_INITIAL_STATE ")
    ]
    if len(proof_lines) != 1 or json.loads(proof_lines[0]) != initial_state:
        raise RuntimeError("accepted profile initial-state record differs from preserved unit.log")
    return {
        "acceptance_sha256": PROFILE_ACCEPTANCE_SHA256,
        "exact_stop_sha256": PROFILE_EXACT_STOP_SHA256,
        "unit": PROFILE_UNIT,
        "invocation_id": PROFILE_INVOCATION_ID,
        "files": observed_files,
        "initial_state_sha256": hashlib.sha256(
            json.dumps(initial_state, sort_keys=True, separators=(",", ":")).encode()
        ).hexdigest(),
        "optimizer_attempts": acceptance["optimizer_attempts"],
        "optimizer_completed_updates": acceptance["optimizer_completed_updates"],
        "scientific_fits": acceptance["scientific_fits"],
        "quality_score": acceptance["quality_score"],
    }


def _validate_profile_initial_state(record: dict[str, object]) -> None:
    """Require the accepted 211→467/23→25 parent-preserving profile proof."""
    expected = {
        "schema": "fg19-child-allthree-profile-initial-state.v1",
        "parent_run": PARENT_RUN,
        "parent_invocation_id": PARENT_INVOCATION,
        "parent_checkpoint_sha256": PARENT_EP3_SHA256,
        "parent_acceptance_sha256": PARENT_ACCEPTANCE_SHA256,
        "parent_exact_stop_sha256": PARENT_EXACT_STOP_SHA256,
        "dictionary_acceptance_sha256": DICTIONARY_ACCEPTANCE_SHA256,
        "dictionary_cache_sha256": DICTIONARY_SHA256,
        "split_manifest_sha256": P["split_sha256"],
        "source_commit": P["source_commit"],
        "profile": {
            "sequence_length": 20000,
            "batch": 16,
            "chunk": 2000,
            "warmup_batches": 2,
            "measured_batches": 4,
            "batch_count": 6,
            "updates_per_batch": 10,
            "optimizer_attempts": 60,
            "input_representation": "ema_sparse",
            "objective": "nll",
        },
        "parent_acceptance_status": "ACCEPTED",
    }
    if any(record.get(key) != value for key, value in expected.items()):
        raise RuntimeError("profile initial-state identity or worst-shape geometry differs")
    initialization = record.get("initialization")
    if not isinstance(initialization, dict):
        raise RuntimeError("profile initial-state extension evidence is missing")
    expected_initialization = {
        "parent_input_width": 211,
        "child_input_width": 467,
        "parent_output_width": 23,
        "child_output_width": 25,
        "parent_trunk_and_prefix_equal": True,
        "new_input_columns_zero": True,
        "new_logvariance_rows_zero": True,
        "normalization_prefix_equal": True,
        "normalization_suffix_mean_zero_std_one": True,
        "finite_initial_state": True,
    }
    if any(initialization.get(key) != value for key, value in expected_initialization.items()):
        raise RuntimeError("profile did not preserve the parent trunk/prefix or zero extensions")
    if not _is_sha256(initialization.get("parent_state_fingerprint")) or not _is_sha256(
        initialization.get("initial_child_state_fingerprint")
    ):
        raise RuntimeError("profile initial-state tensor fingerprints are missing")



def _control_receipt_bytes() -> tuple[bytes, bytes]:
    acceptance_raw = base64.b64decode(CONTROL_ACCEPTANCE_B64, validate=True)
    stop_raw = base64.b64decode(CONTROL_EXACT_STOP_B64, validate=True)
    if (
        hashlib.sha256(acceptance_raw).hexdigest() != CONTROL_ACCEPTANCE_SHA256
        or hashlib.sha256(stop_raw).hexdigest() != CONTROL_EXACT_STOP_SHA256
    ):
        raise RuntimeError("bound CONTROL acceptance/stop bytes changed")
    return acceptance_raw, stop_raw


def _control_identity(acceptance_raw: bytes, stop_raw: bytes) -> dict[str, object]:
    acceptance = json.loads(acceptance_raw)
    stop = json.loads(stop_raw)
    if (
        not isinstance(acceptance, dict)
        or not isinstance(stop, dict)
        or acceptance.get("schema") != "fg19-child-control-fit-terminal-acceptance.v1"
        or acceptance.get("status") != "ACCEPTED"
        or acceptance.get("run_name") != CONTROL_RUN
        or acceptance.get("unit") != CONTROL_UNIT
    ):
        raise RuntimeError("CONTROL predecessor lacks the accepted frozen run identity")
    invocation = acceptance.get("invocation_id")
    if not isinstance(invocation, str) or not re.fullmatch(r"[0-9a-f]{32}", invocation):
        raise RuntimeError("CONTROL predecessor invocation identity is malformed")
    if (
        stop.get("unit") != CONTROL_UNIT
        or stop.get("invocation_id") != invocation
        or stop.get("acceptance_sha256") != CONTROL_ACCEPTANCE_SHA256
    ):
        raise RuntimeError("CONTROL exact stop does not cite the exact accepted invocation")
    before, after = stop.get("before"), stop.get("after")
    if not isinstance(before, dict) or not isinstance(after, dict):
        raise RuntimeError("CONTROL exact-stop states are missing")
    if (
        before.get("InvocationID") != invocation
        or before.get("MainPID") != "0"
        or before.get("ExecMainCode") != "1"
        or before.get("ExecMainStatus") != "0"
        or before.get("ActiveState") != "active"
        or before.get("SubState") != "exited"
        or after.get("LoadState") != "not-found"
        or after.get("ActiveState") != "inactive"
        or after.get("SubState") != "dead"
        or after.get("MainPID") != "0"
        or after.get("InvocationID") != ""
        or stop.get("populated_before") != {}
        or stop.get("populated_after") != {}
    ):
        raise RuntimeError("CONTROL predecessor was not accepted and exactly stopped after native exit0")
    return {
        "acceptance_sha256": CONTROL_ACCEPTANCE_SHA256,
        "exact_stop_sha256": CONTROL_EXACT_STOP_SHA256,
        "run_name": CONTROL_RUN,
        "unit": CONTROL_UNIT,
        "invocation_id": invocation,
        "status": "ACCEPTED_AND_EXACT_STOPPED",
    }


def _trainer_argv() -> list[str]:
    """Return the frozen direct canonical trainer argv for the EMA fit."""
    digest = hashlib.sha256(json.dumps(TRAINER_ARGV, separators=(",", ":")).encode()).hexdigest()
    if digest != TRAINER_ARGV_SHA256:
        raise RuntimeError("EMA canonical trainer argv digest changed")
    return list(TRAINER_ARGV)


def main() -> None:
    """Run fresh read-only gates, then admit one create-only EMA fit."""
    profile_acceptance_raw, profile_stop_raw = _profile_receipt_bytes()
    control_acceptance_raw, control_stop_raw = _control_receipt_bytes()
    control_predecessor = _control_identity(control_acceptance_raw, control_stop_raw)
    receipt_bytes, staged_pins = _decode_staged_receipts()
    receipt_bytes.update({"CONTROL_TERMINAL_ACCEPTANCE.json": control_acceptance_raw, "CONTROL_EXACT_STOP.json": control_stop_raw})
    staged_pins.update({"CONTROL_TERMINAL_ACCEPTANCE.json": CONTROL_ACCEPTANCE_SHA256, "CONTROL_EXACT_STOP.json": CONTROL_EXACT_STOP_SHA256})
    args = _trainer_argv()
    if (
        B.is_symlink()
        or not B.is_dir()
        or DATA.resolve(strict=True) != B / "data"
        or SOURCE.is_symlink()
        or SOURCE.resolve(strict=True) != SOURCE
    ):
        raise RuntimeError("campaign/data/source root unsafe")
    _physical(OUTPUT)
    _physical(RUN_DIR)
    _physical(PROFILE_OUTPUT)
    _physical(PROFILE_RUN_DIR)
    if not PYTHON.is_file() or not os.access(PYTHON, os.X_OK):
        raise FileNotFoundError("pinned project interpreter unavailable")
    _physical(SPLIT)
    if SPLIT.is_symlink() or _sha(SPLIT) != P["split_sha256"]:
        raise RuntimeError("F0 split changed")
    if os.path.lexists(B / "runtime/STOP_ADMISSION.json"):
        raise RuntimeError("campaign admission stopped")
    if any(os.path.lexists(path) for path in (OUTPUT, RUN_DIR)):
        raise FileExistsError("EMA output/run path exists")
    if (
        _run(["systemctl", "--user", "show", "--all", UNIT, "-p", "LoadState", "--value"]).strip()
        != "not-found"
    ):
        raise RuntimeError("new EMA unit exists")
    source_count = _source_identity()
    metadata_pins = _metadata_identity()
    cache = _cache_identity()
    dictionary = _dictionary_identity()
    parent_checkpoint = _parent_checkpoint_identity()
    data = _data_identity()
    parent, populated, group = _parent()
    gpu, foreign = _gpu()
    profile = _profile_identity(profile_acceptance_raw, profile_stop_raw)
    scratch_root = _physical(B / "research_tmp")
    scratch = _run(["findmnt", "-T", str(scratch_root), "-n", "-o", "FSTYPE,SOURCE,TARGET"]).strip()
    statvfs = os.statvfs(scratch_root)
    free = statvfs.f_bavail * statvfs.f_frsize
    if scratch.split()[0] in {"tmpfs", "ramfs"} or free < 25 * (1 << 30):
        raise RuntimeError("physical scratch free space below 25 GiB")
    if any(os.path.lexists(path) for path in (OUTPUT, RUN_DIR)):
        raise FileExistsError("EMA destination appeared during admission")
    if (
        _run(["systemctl", "--user", "show", "--all", UNIT, "-p", "LoadState", "--value"]).strip()
        != "not-found"
    ):
        raise RuntimeError("EMA unit appeared during admission")

    OUTPUT.mkdir(mode=0o700)
    for name, raw in receipt_bytes.items():
        with (OUTPUT / name).open("xb") as stream:
            os.fchmod(stream.fileno(), 0o600)
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
    _sync_directory(OUTPUT)
    for name, expected_sha in staged_pins.items():
        if _sha(OUTPUT / name) != expected_sha:
            raise RuntimeError(f"exclusive receipt staging verification failed: {name}")
    with (OUTPUT / "PROFILE_TERMINAL_ACCEPTANCE.json").open("xb") as stream:
        os.fchmod(stream.fileno(), 0o600)
        stream.write(profile_acceptance_raw)
        stream.flush()
        os.fsync(stream.fileno())
    with (OUTPUT / "PROFILE_EXACT_STOP.json").open("xb") as stream:
        os.fchmod(stream.fileno(), 0o600)
        stream.write(profile_stop_raw)
        stream.flush()
        os.fsync(stream.fileno())
    _sync_directory(OUTPUT)
    if (
        _sha(OUTPUT / "PROFILE_TERMINAL_ACCEPTANCE.json") != PROFILE_ACCEPTANCE_SHA256
        or _sha(OUTPUT / "PROFILE_EXACT_STOP.json") != PROFILE_EXACT_STOP_SHA256
    ):
        raise RuntimeError("exact profile receipt staging verification failed")
    admission = {
        "schema": "fg19-child-ema-fit-admission.v1",
        "created_utc": dt.datetime.now(dt.UTC).isoformat(),
        "unit": UNIT,
        "run_name": RUN,
        "source_commit": P["source_commit"],
        "source_manifest_sha256": P["source_manifest_sha256"],
        "source_files_verified": source_count,
        "metadata_json_sha256_pins": metadata_pins,
        "cache": cache,
        "dictionary": dictionary,
        "parent_acceptance_sha256": PARENT_ACCEPTANCE_SHA256,
        "parent_exact_stop_sha256": PARENT_EXACT_STOP_SHA256,
        "parent_checkpoint_sha256": PARENT_EP3_SHA256,
        "parent_checkpoint_identity": parent_checkpoint,
        "child_profile": profile,
        "control_predecessor": control_predecessor,
        "staged_receipt_sha256": {
            **staged_pins,
            "PROFILE_TERMINAL_ACCEPTANCE.json": PROFILE_ACCEPTANCE_SHA256,
            "PROFILE_EXACT_STOP.json": PROFILE_EXACT_STOP_SHA256,
        },
        "split_sha256": P["split_sha256"],
        "data_identity_stats_only": data,
        "parent": parent,
        "populated": populated,
        "parent_memory_events": (group / "memory.events").read_text(),
        "parent_memory_events_local": (group / "memory.events.local").read_text(),
        "gpu": gpu,
        "foreign_gpu_processes_preserved": foreign,
        "scratch": scratch,
        "scratch_free_bytes": free,
        "recipe": {
            "trainer_argv_sha256": TRAINER_ARGV_SHA256,
            "seed": 1001,
            "fit_groups": 11940,
            "held_out_evaluation_groups_excluded": 468,
            "batch_size": 16,
            "chunk_rows": 2000,
            "epochs": 6,
            "checkpoint_epoch_zero_based": 5,
            "expected_optimizer_updates": 44760,
            "expected_updates_are_arithmetic_not_observed": True,
            "representation_mode": "ema",
            "objective": "wmse",
            "inherited_parent_preprocessing": True,
            "evaluation_during_fit": False,
        },
        "worker": {
            "cpu_quota": "100%",
            "memory_high": 7500000000,
            "memory_max": FIT_MEMORY,
            "swap_max": 0,
            "cuda_allocator_bytes": 4294967296,
            "cuda_free_reserve_bytes": 1000000000,
            "runtime_max_seconds": 86400,
            "loader_workers": 0,
        },
    }
    _write(OUTPUT / "ADMISSION.json", admission)
    _sync_directory(OUTPUT)
    command = [str(PYTHON), "-u", str(SOURCE / "scripts/train_rnn.py"), *args]
    env = {
        "PYTHONPATH": str(SOURCE / "src"),
        "PYTHONDONTWRITEBYTECODE": "1",
        "WNN_PROJECT_ROOT": str(DATA),
        "WNN_PORTABLE_DATA_MANIFEST": str(REGISTRY),
        "WNN_GPU_MEMORY_BYTES": "4294967296",
        "WNN_LOADER_WORKERS": "0",
        "WNN_LOADER_RAM_GB": "1",
        "WNN_THREADS": "1",
        "OMP_NUM_THREADS": "1",
        "OPENBLAS_NUM_THREADS": "1",
        "MKL_NUM_THREADS": "1",
        "NUMEXPR_NUM_THREADS": "1",
        "CUDA_VISIBLE_DEVICES": GPU,
        "NVIDIA_TF32_OVERRIDE": "0",
        "CUBLAS_WORKSPACE_CONFIG": ":4096:8",
        "TMPDIR": str(B / "research_tmp"),
        "WNN_TMP_ROOT": str(B / "research_tmp"),
    }
    service = [
        "systemd-run",
        "--user",
        "--unit=" + UNIT,
        "--property=Type=exec",
        "--property=RemainAfterExit=yes",
        "--property=Slice=wnn-campaign.slice",
        "--property=CPUQuota=100%",
        "--property=MemoryHigh=7500000000",
        "--property=MemoryMax=8000000000",
        "--property=MemorySwapMax=0",
        "--property=RuntimeMaxSec=86400",
        "--property=TimeoutStopSec=45",
        "--property=StandardOutput=append:" + str(OUTPUT / "unit.log"),
        "--property=StandardError=append:" + str(OUTPUT / "unit.log"),
        "--working-directory=" + str(SOURCE),
    ]
    service.extend("--setenv=" + key + "=" + value for key, value in env.items())
    service.extend(command)
    try:
        result = subprocess.run(service, capture_output=True, timeout=30)
        submission = {
            "returncode": result.returncode,
            "stdout_b64": base64.b64encode(result.stdout).decode(),
            "stderr_b64": base64.b64encode(result.stderr).decode(),
            "outcome": "submitted" if result.returncode == 0 else "unknown_or_failed",
        }
    except subprocess.TimeoutExpired as error:
        submission = {
            "returncode": None,
            "stdout_b64": base64.b64encode(error.stdout or b"").decode(),
            "stderr_b64": base64.b64encode(error.stderr or b"").decode(),
            "outcome": "unknown",
        }
    except OSError as error:
        submission = {
            "returncode": None,
            "stdout_b64": "",
            "stderr_b64": "",
            "outcome": "unknown",
            "error": str(error),
        }
    fields = ["InvocationID", "ExecStart", "ActiveState", "SubState", "MainPID", "ControlGroup"]
    try:
        show = subprocess.run(
            [
                "systemctl",
                "--user",
                "show",
                "--all",
                UNIT,
                *sum((["-p", field] for field in fields), []),
            ],
            capture_output=True,
            timeout=10,
        )
        post_submit = {
            "returncode": show.returncode,
            "stdout_b64": base64.b64encode(show.stdout).decode(),
            "stderr_b64": base64.b64encode(show.stderr).decode(),
            "outcome": "captured" if show.returncode == 0 else "query_failed",
        }
    except subprocess.TimeoutExpired as error:
        post_submit = {
            "returncode": None,
            "stdout_b64": base64.b64encode(error.stdout or b"").decode(),
            "stderr_b64": base64.b64encode(error.stderr or b"").decode(),
            "outcome": "timeout_unknown",
        }
    except OSError as error:
        post_submit = {
            "returncode": None,
            "stdout_b64": "",
            "stderr_b64": "",
            "outcome": "query_error",
            "error": str(error),
        }
    launch = {
        "schema": "fg19-child-ema-fit-launch.v1",
        "created_utc": dt.datetime.now(dt.UTC).isoformat(),
        "unit": UNIT,
        "command": service,
        "submission": submission,
        "control_predecessor": control_predecessor,
        "systemctl_after_submission": post_submit,
        "unknown_outcome_policy": "never retry; inspect this exact unit and durable EMA output",
    }
    _write(OUTPUT / "LAUNCH.json", launch)
    _sync_directory(OUTPUT)
    print(
        json.dumps(
            {
                name: base64.b64encode((OUTPUT / name).read_bytes()).decode()
                for name in ("ADMISSION.json", "LAUNCH.json")
            }
        )
    )


if __name__ == "__main__":
    main()
